#![deny(unsafe_code)]

//! Tauri application bootstrap library.

mod commands;
pub mod contract;
mod logging;
mod thumbnail_protocol;

use std::{collections::BTreeSet, fs};

use contract::{AppInfo, LicenseInfo};
use picker_ml::{ModelInfo, ModelState};
use serde::Deserialize;

/// SBOM generated by `scripts/generate-sbom.py`, bundled for the license screen.
const SBOM: &str = include_str!("../../docs/sbom.cdx.json");

#[derive(Deserialize)]
struct Sbom {
    components: Vec<SbomComponent>,
}

#[derive(Deserialize)]
struct SbomComponent {
    name: String,
    licenses: Vec<SbomLicenseEntry>,
}

#[derive(Deserialize)]
struct SbomLicenseEntry {
    license: SbomLicense,
}

#[derive(Deserialize)]
struct SbomLicense {
    name: String,
}

/// Returns the application and model license information defined by the UI contract.
#[tauri::command]
fn get_app_info(state: tauri::State<'_, commands::AppState>) -> AppInfo {
    app_info(&state.model_list())
}

fn app_info(models: &[ModelInfo]) -> AppInfo {
    AppInfo {
        version: env!("CARGO_PKG_VERSION").to_owned(),
        dependency_licenses: dependency_licenses(SBOM),
        model_licenses: model_licenses(models),
    }
}

/// Lists each dependency once per license. A malformed SBOM yields an empty list.
fn dependency_licenses(sbom: &str) -> Vec<LicenseInfo> {
    let Ok(sbom) = serde_json::from_str::<Sbom>(sbom) else {
        return Vec::new();
    };
    let unique: BTreeSet<(String, String)> = sbom
        .components
        .into_iter()
        .flat_map(|component| {
            let name = component.name;
            component
                .licenses
                .into_iter()
                .map(move |entry| (name.clone(), entry.license.name))
        })
        .collect();
    unique
        .into_iter()
        .map(|(name, license)| LicenseInfo { name, license })
        .collect()
}

/// Lists the licenses of models whose files are installed and verified.
fn model_licenses(models: &[ModelInfo]) -> Vec<LicenseInfo> {
    models
        .iter()
        .filter(|model| model.state == ModelState::Ready)
        .map(|model| LicenseInfo {
            name: model.id.clone(),
            license: model.license.clone(),
        })
        .collect()
}

/// Starts the Tauri desktop application.
pub fn run() {
    tauri::Builder::default()
        .invoke_handler(tauri::generate_handler![
            get_app_info,
            commands::roots_list,
            commands::root_add,
            commands::root_remove,
            commands::root_set_enabled,
            commands::rescan_root,
            commands::asset_search,
            commands::asset_detail,
            commands::finder_reveal,
            commands::log_reveal,
            commands::viewport_update,
            commands::index_status,
            commands::pause_index,
            commands::resume_index,
            commands::tags_list,
            commands::tag_create,
            commands::tag_rename,
            commands::tag_delete,
            commands::tag_set_parent,
            commands::tag_merge,
            commands::tag_aliases,
            commands::tag_add_alias,
            commands::tag_remove_alias,
            commands::tag_assign,
            commands::tag_convert_to_custom,
            commands::custom_suggest,
            commands::custom_train,
            commands::review_candidates,
            commands::review_confirm,
            commands::feedback_undo,
            commands::portable_export,
            commands::portable_import,
            commands::setting_get,
            commands::setting_set,
            commands::xmp_export,
            commands::cache_clear,
            commands::tag_reject,
            commands::auto_tag,
            commands::tag_remove,
            commands::asset_filter,
            commands::duplicates_list,
            commands::palette_list,
            commands::color_set,
            commands::color_reset,
            commands::albums_list,
            commands::album_create,
            commands::album_rename,
            commands::album_delete,
            commands::album_add_assets,
            commands::album_remove_assets,
            commands::album_reorder,
            commands::album_assets,
            commands::album_create_auto,
            commands::album_set_query,
            commands::album_query,
            commands::album_auto_page,
            commands::models_list,
            commands::model_install,
            commands::model_activate,
            commands::model_remove,
            commands::embedding_status,
            commands::embedding_index,
            commands::semantic_search,
            commands::similar_assets,
        ])
        .register_uri_scheme_protocol("asset", |_context, request| {
            thumbnail_protocol::handle(request)
        })
        .setup(|app| {
            use tauri::Manager;

            match app
                .path()
                .app_log_dir()
                .map_err(std::io::Error::other)
                .and_then(|dir| logging::init(&dir))
            {
                Ok(path) => log::info!(
                    "Picker {} started; log file {}",
                    env!("CARGO_PKG_VERSION"),
                    path.display()
                ),
                Err(error) => eprintln!("logging unavailable: {error}"),
            }
            let data_dir = app.path().app_data_dir()?;
            fs::create_dir_all(&data_dir)?;
            let database = commands::default_database(&data_dir);
            let cache = commands::default_cache(&data_dir);
            let library = picker_core::Library::open(&database, &cache)?;
            thumbnail_protocol::set_cache_root(library.cache_root().to_path_buf());
            let models = picker_ml::ModelRegistry::open(data_dir.join("models"));
            // Keep one daily database snapshot for a week (design 6.3).
            let now = std::time::SystemTime::now()
                .duration_since(std::time::UNIX_EPOCH)
                .ok()
                .and_then(|elapsed| i64::try_from(elapsed.as_secs()).ok())
                .unwrap_or(0);
            if let Err(error) =
                library.snapshot_if_due(&data_dir.join("snapshots"), now, 24 * 60 * 60, 7)
            {
                log::error!("database snapshot failed: {error}");
            }
            if let Err(error) = library.ensure_default_auto_albums() {
                log::error!("default albums unavailable: {error}");
            }
            app.manage(commands::AppState::new(library, models));
            let handle = app.handle().clone();
            match picker_core::WorkerPool::start(
                picker_core::PoolConfig::new(&database, &cache),
                std::sync::Arc::new(picker_core::SystemPower),
                std::sync::Arc::new(move || commands::emit_index_progress(&handle)),
            ) {
                Ok(pool) => app.state::<commands::AppState>().set_workers(pool),
                Err(error) => log::error!("background workers unavailable: {error}"),
            }
            let handle = app.handle().clone();
            match picker_core::WatchService::start(
                picker_core::WatchConfig::new(&database, &cache),
                std::sync::Arc::new(move || commands::emit_index_progress(&handle)),
            ) {
                Ok(service) => app.state::<commands::AppState>().set_watch(service),
                Err(error) => log::error!("folder watching unavailable: {error}"),
            }
            // Loaded after the workers start, so they receive the model too.
            if let Err(error) = app.state::<commands::AppState>().reload_embedder() {
                log::warn!("embedding model unavailable: {error}");
            }
            let _core = create_core();
            Ok(())
        })
        .run(tauri::generate_context!())
        .expect("error while running the Picker application");
}

/// Returns the application core used by the desktop bootstrap.
#[must_use]
pub const fn create_core() -> picker_core::Core {
    picker_core::Core::new()
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::contract::{CommandContract, GetAppInfo, GetAppInfoRequest};

    #[test]
    fn ids_and_paths_are_bounded() {
        assert!(commands::parse_id("1").is_ok());
        assert!(commands::parse_id("0").is_err());
        assert!(commands::parse_id("-1").is_err());
        assert!(commands::parse_id("../../etc/passwd").is_err());
        let data = std::path::Path::new("/tmp/picker");
        assert_eq!(
            commands::default_database(data),
            std::path::PathBuf::from("/tmp/picker/library.sqlite3")
        );
        assert_eq!(
            commands::default_cache(data),
            std::path::PathBuf::from("/tmp/picker/thumbnails")
        );
    }

    #[test]
    fn reloading_without_an_installed_model_clears_the_embedder() {
        let data = tempfile::tempdir().expect("data");
        let library =
            picker_core::Library::open_in_memory(data.path().join("cache")).expect("library");
        let models = picker_ml::ModelRegistry::open(data.path().join("models"));
        let state = commands::AppState::new(library, models);
        state.reload_embedder().expect("reload");
        assert!(state.model_list().iter().all(|model| !model.active));
    }

    #[test]
    fn sample_app_info_command_matches_the_wire_contract() {
        let request =
            serde_json::to_value(GetAppInfoRequest::default()).expect("request should serialize");
        assert_eq!(GetAppInfo::NAME, "get_app_info");
        assert_eq!(request, serde_json::json!({}));

        let response = serde_json::to_value(app_info(&[])).expect("response should serialize");
        assert_eq!(response["version"], env!("CARGO_PKG_VERSION"));
        assert!(response["dependencyLicenses"]
            .as_array()
            .is_some_and(|licenses| !licenses.is_empty()));
        assert_eq!(response["modelLicenses"], serde_json::json!([]));
    }

    #[test]
    fn asset_filter_request_maps_the_three_tag_sets() {
        let request: crate::contract::AssetFilterRequest =
            serde_json::from_value(serde_json::json!({
                "cursor": null,
                "pageSize": 50,
                "tagsAll": ["1"],
                "tagsAny": ["2", "3"],
                "tagsNone": ["4"],
                "includeSuggested": true,
                "formats": [],
                "minWidth": null,
                "minHeight": null,
                "capturedFrom": null,
                "capturedTo": null,
                "colors": ["red"],
                "colorScope": "any"
            }))
            .expect("request should deserialize");
        let filter = commands::filter_from_request(&request).expect("filter");
        assert_eq!(filter.tags.all, vec![1]);
        assert_eq!(filter.tags.any, vec![2, 3]);
        assert_eq!(filter.tags.none, vec![4]);
        assert!(filter.tags.include_suggested);

        let colors = commands::color_condition(&request).expect("colors");
        assert_eq!(colors.palette_ids, vec!["red".to_owned()]);
        assert_eq!(colors.scope, picker_core::ColorScope::AnyOfThree);

        let mut bad_scope = request.clone();
        bad_scope.color_scope = "dominant".to_owned();
        assert!(commands::color_condition(&bad_scope).is_err());

        let mut invalid = request;
        invalid.tags_none = vec!["../1".to_owned()];
        assert!(commands::filter_from_request(&invalid).is_err());
    }

    #[test]
    fn asset_filter_request_rejects_the_old_single_mode_shape() {
        let old = serde_json::json!({
            "cursor": null, "pageSize": 50, "tagIds": ["1"], "tagMode": "all",
            "includeSuggested": false, "formats": [], "minWidth": null,
            "minHeight": null, "capturedFrom": null, "capturedTo": null
        });
        assert!(serde_json::from_value::<crate::contract::AssetFilterRequest>(old).is_err());
    }

    #[test]
    fn album_query_views_round_trip_through_tag_references() {
        let cache = tempfile::tempdir().expect("cache");
        let library = picker_core::Library::open_in_memory(cache.path()).expect("library");
        let tag = library
            .create_tag("beach", "海辺", None, None)
            .expect("tag");
        let view = crate::contract::AlbumQueryView {
            tags_all: vec![tag.id.to_string()],
            tags_any: Vec::new(),
            tags_none: Vec::new(),
            include_suggested: false,
            colors: vec!["blue".to_owned()],
            color_scope: "any".to_owned(),
            formats: Vec::new(),
            min_width: None,
            min_height: None,
            captured_from: None,
            captured_to: None,
            added_within_days: Some(30),
            untagged: false,
            has_suggested: true,
        };
        let query = commands::album_query_from_view(&library, &view).expect("query");
        assert_eq!(query.tags_all[0].canonical_name, "beach");
        assert!(query.colors_any_of_three);
        assert_eq!(
            commands::album_query_view(&library, query).expect("view"),
            view
        );

        let mut bad_scope = view.clone();
        bad_scope.color_scope = "all".to_owned();
        assert!(commands::album_query_from_view(&library, &bad_scope).is_err());
        let mut unknown_tag = view;
        unknown_tag.tags_none = vec!["999".to_owned()];
        assert!(commands::album_query_from_view(&library, &unknown_tag).is_err());
    }

    #[test]
    fn palette_list_returns_the_twelve_colors() {
        let colors = commands::palette_list().expect("palette");
        assert_eq!(colors.len(), 12);
        assert!(colors
            .iter()
            .any(|color| color.id == "red" && color.name_ja == "赤"));
    }

    #[test]
    fn dependency_licenses_come_from_the_bundled_sbom() {
        let licenses = dependency_licenses(SBOM);
        assert!(licenses
            .iter()
            .any(|info| info.name == "tauri" && !info.license.is_empty()));
        let unique: BTreeSet<_> = licenses
            .iter()
            .map(|info| (info.name.as_str(), info.license.as_str()))
            .collect();
        assert_eq!(unique.len(), licenses.len());
    }

    #[test]
    fn malformed_sbom_yields_no_dependency_licenses() {
        assert!(dependency_licenses("").is_empty());
        assert!(dependency_licenses("{\"components\": 1}").is_empty());
    }

    #[test]
    fn only_ready_models_are_listed() {
        let model = |id: &str, state| ModelInfo {
            id: id.to_owned(),
            version: "1".to_owned(),
            license: "Apache-2.0".to_owned(),
            license_url: "https://example.invalid/license".to_owned(),
            size: 1,
            state,
            active: false,
        };
        let licenses = model_licenses(&[
            model("ready", ModelState::Ready),
            model("partial", ModelState::Partial),
            model("missing", ModelState::Missing),
        ]);
        assert_eq!(
            licenses,
            vec![LicenseInfo {
                name: "ready".to_owned(),
                license: "Apache-2.0".to_owned(),
            }]
        );
    }
}
